import { useState, useEffect } from "react";
import axios from "axios";

const useStockData = () => {
  const [data, setData] = useState([]);
  useEffect(() => {
    // 실제 백엔드 API 주소로 변경
    axios.get("/api/stock-data").then(res => setData(res.data));
  }, []);
  return data;
};

export default useStockData;
